{
  "didatica": [
    {
      "campo": "resolucao.antes.texto",
      "depois": "Pergunta de propósito pede a razão de a carta existir. Numa carta, o remetente diz o que quer comunicar. Na frase com While (embora), o mais importante vem depois do elogio: a oração principal. Aqui a frase abre com elogio e termina com a decisão (we are forced to… pass on your manuscript). O phrasal verb (verbo + partícula) 'pass on' tem sentido próprio, que depende do contexto.",
      "motivo": "Explica 'phrasal verb' e 'While' em palavras simples; frases mais curtas e sem ambiguidade."
    },
    {
      "campo": "resolucao.antes.simbolos",
      "depois": [
        ["piece", "texto, obra (aqui, o livro)"],
        ["compelling", "envolvente, convincente"],
        ["thoroughly moving", "profundamente comovente"],
        ["narrative", "narrativa, história contada"],
        ["bothered", "incomodados"],
        ["exclamation point", "ponto de exclamação (!)"],
        ["jarring", "chocante, desagradável de ler"],
        ["I am afraid", "lamento informar (fórmula educada para dar má notícia)"],
        ["forced to", "obrigados a"],
        ["manuscript", "original do livro, texto ainda não publicado"],
        ["pass on", "aqui, recusar, declinar (não é 'passar adiante')"],
        ["Best of luck", "boa sorte"]
      ],
      "motivo": "Inclui narrative e forced to, usados nos passos, e deixa claro que pass on não é 'passar adiante'."
    },
    {
      "campo": "resolucao.pista",
      "depois": "Depois do elogio inicial, veja o que a editora diz que foi 'forçada' a fazer com o manuscrito. Que decisão é essa?",
      "motivo": "Pista aponta o trecho sem entregar a resposta."
    },
    {
      "campo": "resolucao.passos[1].conta",
      "depois": "Viking Press (editora) → Ms. Walker (autora)",
      "motivo": "Mais curto e fiel ao print; cabe na tela do celular."
    },
    {
      "campo": "resolucao.passos[2].conta",
      "depois": "“While your piece… presents a compelling… narrative, we were bothered”",
      "motivo": "Mantida; é o trecho do contraste."
    },
    {
      "campo": "resolucao.passos[2].porque",
      "depois": "While = embora. A editora elogia a narrativa (envolvente e comovente), mas diz que se incomodou. O que vem depois do contraste pesa mais.",
      "motivo": "Frase mais curta e direta."
    },
    {
      "campo": "resolucao.passos[3].conta",
